import type { Config } from "tailwindcss";
import m3 from "./lib/m3-theme.json";

// Material 3 theme. Every color comes from lib/m3-theme.json, generated by
// scripts/m3-theme.mjs from Agora's blue with Google's material-color-utilities
// (fidelity scheme). M3 role names are first-class ("bg-surface-container",
// "text-on-primary"). Agora's older color names and Tailwind's emerald, amber
// and red are remapped onto M3 roles and harmonized tonal palettes, so pages
// written before the switch follow the scheme too.

const r = m3.roles;
const p = m3.palettes;
const c = m3.custom;
const customColor = (k: keyof typeof c) => ({ DEFAULT: c[k].DEFAULT, on: c[k].on, container: c[k].container, "on-container": c[k]["on-container"] });

// M3 type scale: [size, line height, tracking, weight]. Headlines are regular weight; titles and labels medium.
const type = (size: string, lh: string, ls: string, weight: string) => [size, { lineHeight: lh, letterSpacing: ls, fontWeight: weight }] as [string, { lineHeight: string; letterSpacing: string; fontWeight: string }];

export default {
  content: ["./app/**/*.{ts,tsx}", "./components/**/*.{ts,tsx}"],
  theme: {
    extend: {
      colors: {
        ...r,
        success: customColor("success"),
        warning: customColor("warning"),
        "src-own": customColor("src-own"),
        "src-state": customColor("src-state"),
        "src-coop": customColor("src-coop"),
        "src-other": customColor("src-other"),
        "src-small": customColor("src-small"),
        // Legacy Agora names, now M3 roles.
        navy: { DEFAULT: r["on-surface"], 600: r["on-surface-variant"], 50: r["secondary-container"] },
        maroon: { DEFAULT: r.primary, 600: p.primary[800], 50: p.primary[50] },
        rose: p.primary[300],
        steel: r.outline,
        tint: r["surface-container"],
        page: r["surface-container-low"],
        line: r["outline-variant"],
        slate: { DEFAULT: r["on-surface-variant"] },
        green: { DEFAULT: c.success.DEFAULT, 50: c.success.container },
        // Status palettes, harmonized with the seed.
        emerald: c.success.ramp,
        amber: c.warning.ramp,
        red: p.error,
      },
      fontFamily: {
        sans: ["Roboto", "ui-sans-serif", "system-ui", "-apple-system", '"Segoe UI"', "sans-serif"],
        mono: ['"Roboto Mono"', "ui-monospace", "SFMono-Regular", "monospace"],
      },
      // M3 uses two weights: regular and medium.
      fontWeight: { semibold: "500", bold: "500", extrabold: "500", black: "500" },
      letterSpacing: { tighter: "0", tight: "0" },
      fontSize: {
        "display-s": type("36px", "44px", "0", "400"),
        "headline-l": type("32px", "40px", "0", "400"),
        "headline-m": type("28px", "36px", "0", "400"),
        "headline-s": type("24px", "32px", "0", "400"),
        "title-l": type("22px", "28px", "0", "400"),
        "title-m": type("16px", "24px", "0.15px", "500"),
        "title-s": type("14px", "20px", "0.1px", "500"),
        "body-l": type("16px", "24px", "0.5px", "400"),
        "body-m": type("14px", "20px", "0.25px", "400"),
        "body-s": type("12px", "16px", "0.4px", "400"),
        "label-l": type("14px", "20px", "0.1px", "500"),
        "label-m": type("12px", "16px", "0.5px", "500"),
        "label-s": type("11px", "16px", "0.5px", "500"),
      },
      // M3 shape scale: extra-small 4, small 8, medium 12, large 16, extra-large 28.
      borderRadius: { sm: "4px", DEFAULT: "4px", md: "8px", lg: "12px", xl: "16px", "2xl": "16px", "3xl": "28px" },
      // M3 elevation levels 1–3.
      boxShadow: {
        card: "0 1px 2px 0 rgb(0 0 0 / 0.3), 0 1px 3px 1px rgb(0 0 0 / 0.15)",
        "elevation-1": "0 1px 2px 0 rgb(0 0 0 / 0.3), 0 1px 3px 1px rgb(0 0 0 / 0.15)",
        "elevation-2": "0 1px 2px 0 rgb(0 0 0 / 0.3), 0 2px 6px 2px rgb(0 0 0 / 0.15)",
        "elevation-3": "0 4px 8px 3px rgb(0 0 0 / 0.15), 0 1px 3px 0 rgb(0 0 0 / 0.3)",
      },
    },
  },
  plugins: [],
} satisfies Config;
